"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["52540"],{8082(e){e.exports=JSON.parse('{"id":"FIN-550","slug":"tax-avoidance","term":"Tax Avoidance","also_known_as":[],"difficulty":"Beginner","definition":"Tax avoidance is the legal use of tax rules to reduce the amount of tax owed, for example by claiming allowances, deductions and reliefs or by structuring transactions in a tax-efficient way.","explanation":["Tax systems contain many rules that reduce tax for particular actions. Saving into a pension, investing through a tax-advantaged account, giving to charity or claiming business expenses are all legal ways to lower a tax bill. Using these rules is a form of tax avoidance in the broad sense, and much of it is exactly what governments intend.","For example, contributing to a retirement account that offers tax relief reduces taxable income, which is a legitimate use of the rules.","The term becomes controversial when arrangements follow the letter of the law but defeat its purpose. Complex schemes that shift profits to low-tax countries or create artificial losses may be technically legal but widely seen as unfair. Many countries have introduced anti-avoidance rules that allow tax authorities to challenge arrangements whose main purpose is to avoid tax.","Tax avoidance differs fundamentally from tax evasion. Avoidance works within the law, even if aggressively; evasion breaks the law by hiding income or giving false information, and is a crime."],"note":"","total":1725,"prev":{"slug":"tax-audit","term":"Tax Audit"},"next":{"slug":"tax-base","term":"Tax Base"}}')}}]);